        self.m1.commutes_with(self.m2)

    def setup(self, n_modes):
        self.m1 = _make_mon(0b0011, n_modes)
        self.m2 = _make_mon(0b0110, n_modes)
        self.m3 = _make_mon(0b1100, n_modes)

